<?php
require_once __DIR__.'/common.php';require_admin(); require_staff();
$edit=null;if(isset($_GET['edit'])){$s=$conn->prepare('SELECT * FROM danhmuc WHERE madanhmuc=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$conn->query('SELECT d.*, (SELECT COUNT(*) FROM tintuc t WHERE t.madanhmuc=d.madanhmuc) AS so_tin, (SELECT COUNT(*) FROM chuyenmuc c WHERE c.madanhmuc=d.madanhmuc) AS so_chuyenmuc FROM danhmuc d ORDER BY d.madanhmuc DESC')->fetchAll();
admin_header('QUẢN LÝ DANH MỤC');
?><section class="panel"><h2><?=$edit?'Cập nhật danh mục':'Thêm danh mục mới'?></h2><form method="post" action="xulyquanlydanhmuc.php"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="madanhmuc" value="<?=h($edit['madanhmuc']??'')?>"><div class="grid"><div class="field"><label>Mã danh mục</label><input name="ma_danh_muc" maxlength="20" value="<?=h($edit['ma_danh_muc']??'')?>" placeholder="DM09"></div><div class="field"><label>Tên danh mục *</label><input name="tendanhmuc" required maxlength="150" value="<?=h($edit['tendanhmuc']??'')?>"></div><div class="field"><label>Thể loại</label><input name="theloai" maxlength="100" value="<?=h($edit['theloai']??'')?>"></div><div class="field"><label>Trạng thái</label><select name="trang_thai"><option value="1" <?=((int)($edit['trang_thai']??1)===1?'selected':'')?>>Hiển thị</option><option value="0" <?=((int)($edit['trang_thai']??1)===0?'selected':'')?>>Ẩn</option></select></div></div><div class="field"><label>Mô tả</label><textarea name="mo_ta"><?=h($edit['mo_ta']??'')?></textarea></div><button type="submit"><?=$edit?'Lưu thay đổi':'Thêm danh mục'?></button><?php if($edit):?> <a class="btn secondary" href="quanlydanhmuc.php">Hủy</a><?php endif;?></form></section>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>Mã</th><th>Tên danh mục</th><th>Thể loại</th><th>Tin</th><th>Chuyên mục</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['madanhmuc']?></td><td><?=h($r['ma_danh_muc'])?></td><td><?=h($r['tendanhmuc'])?></td><td><?=h($r['theloai'])?></td><td><?=$r['so_tin']?></td><td><?=$r['so_chuyenmuc']?></td><td><?=$r['trang_thai']?'Hiển thị':'Ẩn'?></td><td><div class="actions"><a class="btn small" href="?edit=<?=$r['madanhmuc']?>">Sửa</a><form method="post" action="xulyquanlydanhmuc.php" onsubmit="return confirm('Xóa danh mục này? Các tin/chuyên mục liên kết sẽ được bỏ liên kết, không bị xóa.');"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="madanhmuc" value="<?=$r['madanhmuc']?>"><button class="danger small">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php admin_footer();?>
